import { CommonModule } from '@angular/common';
import { provideHttpClient, withInterceptorsFromDi } from '@angular/common/http';
import { Injector, NgModule } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { NavigationEnd, Router } from '@angular/router';

import { combineLatest, ReplaySubject } from 'rxjs';
import { filter, map, take } from 'rxjs/operators';

import { ButtonModule } from 'espd-common/button';
import { ApplicationConfig, MODULE_NAME } from 'espd-common/config';
import {
	MessageModule,
	MessageService
} from 'espd-common/i18n';
import { ModalModule } from 'espd-common/modal';
import { NavigationService } from 'espd-common/navigation';
import { PlaceholderService } from 'espd-common/placeholder';
import { ScrollService } from 'espd-common/scroll';
import { SessionModule } from 'espd-common/session';
import { SettingService } from 'espd-common/setting';
import { extractRouteData, ServiceLocator } from 'espd-common/utils';
import { WindowService } from 'espd-common/window';

@NgModule({
	imports: [
		CommonModule,
		ButtonModule,
		MessageModule.forRoot(),
		ModalModule.forRoot(),
		SessionModule.forRoot()
	],
	providers: [
		NavigationService,
		PlaceholderService,
		ScrollService,
		WindowService,
		provideHttpClient(withInterceptorsFromDi())
	],
	exports: [
		BrowserAnimationsModule
	],
})
export class EspdCommonModule {
	private appName: string = '';
	private navEndSubject: ReplaySubject<NavigationEnd> = new ReplaySubject(1);

	constructor(injector: Injector,
		private router: Router,
		private titleService: Title,
		private messageService: MessageService,
		private settingService: SettingService,
		private appConfig: ApplicationConfig) {
		ServiceLocator.injector = injector;

		this.router.events.pipe(
			filter((event): event is NavigationEnd => event instanceof NavigationEnd))
			.subscribe(event => this.navEndSubject.next(event));

		const settingsObs = this.settingService.waitFor(MODULE_NAME);
		const messageObs = this.messageService.waitFor(MODULE_NAME);
		combineLatest([settingsObs, messageObs]).pipe(take(1)).subscribe(() => {
			this.appName = this.settingService.get(this.appConfig.applicationNameSetting);
			this.listenAndUpdatePageTitle();
		});

		this.settingService.init(MODULE_NAME);
		this.messageService.init(MODULE_NAME);
	}

	private listenAndUpdatePageTitle() {
		this.navEndSubject.pipe(
			filter(() => this.appConfig.enableRoutePageTitles),
			extractRouteData(this.router),
			map(routeData => {
				if (routeData.title) {
					const pageTitle = this.messageService.get(routeData.title);
					return this.messageService.get(this.appConfig.pageTitleMessageKey, this.appName, pageTitle);
				} else if (routeData.title === undefined) {
					return this.appName;
				}
				return null;
			}),
			filter((title): title is string => !!title)
		).subscribe(title => this.titleService.setTitle(title));
	}
}